var SPC={"Feathren":{"size":"Medium","speed":30,"dark":60,"type":"Humanoid","spAb":"choose","spAbTrait":"Feathren Ancestry","toolPick":{"n":2,"cats":["art"],"label":"Natural Creator"},"attacks":[{"n":"Talons","die":"1d6","type":"Piercing","range":"5 ft","ab":"STR","note":"Your talons replace the Bludgeoning damage of an Unarmed Strike with Piercing damage."}],"lin":{"label":"Avian Ancestry","opts":["Jay","Owl","Raven","Eagle","Falcon","Hawk","Cardinal","Mockingbird","Parrot"]},"linText":{"Jay":"You know the cantrip Thaumaturgy.","Owl":"You know the cantrip Thaumaturgy.","Raven":"You know the cantrip Thaumaturgy.","Eagle":"You know the cantrip Message.","Falcon":"You know the cantrip Message.","Hawk":"You know the cantrip Message.","Cardinal":"You know the cantrip Prestidigitation.","Mockingbird":"You know the cantrip Prestidigitation.","Parrot":"You know the cantrip Prestidigitation."},"opts":{"label":"Feline Ancestry","n":1,"list":[["Lion","At character level 3 you learn Detect Evil and Good. You always have it prepared.",{}],["Panther","At character level 3 you learn Detect Evil and Good. You always have it prepared.",{}],["Saber-Toothed Tiger","At character level 3 you learn Detect Evil and Good. You always have it prepared.",{}],["Cheetah","At character level 3 you learn Detect Poison and Disease. You always have it prepared.",{}],["Serval","At character level 3 you learn Detect Poison and Disease. You always have it prepared.",{}],["Tiger","At character level 3 you learn Detect Poison and Disease. You always have it prepared.",{}],["Jaguar","At character level 3 you learn Detect Magic. You always have it prepared.",{}],["Lynx","At character level 3 you learn Detect Magic. You always have it prepared.",{}],["Snow Leopard","At character level 3 you learn Detect Magic. You always have it prepared.",{}]]},"traits":[["Darkvision","Darkvision 60 ft."],["Feathren Ancestry","Your mix of bird and cat blood gives you magic. Pick one Avian and one Feline ancestry. Avian: Jay, Owl or Raven give Thaumaturgy. Eagle, Falcon or Hawk give Message. Cardinal, Mockingbird or Parrot give Prestidigitation. Feline: Lion, Panther or Saber-Toothed Tiger give Detect Evil and Good. Cheetah, Serval or Tiger give Detect Poison and Disease. Jaguar, Lynx or Snow Leopard give Detect Magic. You know the Avian cantrip and Identify. At character level 3 you learn the Feline spell. At character level 5 you learn Enhance Ability. You always have these spells prepared. You can cast each of the spells once with no slot and no Material component, regaining the use on a Long Rest. You can also cast them with slots of the right level. Intelligence, Wisdom or Charisma is your spellcasting ability for them, chosen with the ancestries."],["Kindred Speech","You can pass simple ideas to birds and cats of Large size or smaller, griffons included. They understand your words but you gain no special way to understand them. You have Advantage on Wisdom (Animal Handling) checks and on Charisma checks to influence them."],["Natural Creator","A mote of the astral griffon's creative essence lives in you. You have proficiency with two Artisan's Tools of your choice. You can gain proficiency with a new tool in half the normal time."],["Talons","When your Unarmed Strike uses your talons to deal damage, it deals 1d6 Piercing damage instead of Bludgeoning."]],"hb":"GSB24"}};
